<?php
declare(strict_types=1);
require __DIR__.'/harness.php';require __DIR__.'/migration-operations-fixture.php';
use Hostider\Core\{CanonicalJson,Id};
use Hostider\Core\Security\Crypto;
use Hostider\Migration\{Contract};
use Hostider\Migration\Operations\{Vault,Destination,AuthenticatedBackup,Retention};
use Hostider\Migration\Synthetic\{Sandbox,Fixture};
use Hostider\Core\Queue\Queue;

function operationBackup(array &$f): array {return $f['backup']=$f['vault']->backup($f['source'],$f['crypto'],'synthetic-v1');}
function operationForge(array $f,Closure $change): string {$data=$f['source']->capture();$data=$change($data);$id=Contract::hash($data);$plain=CanonicalJson::encode(['data'=>$data,'logical_sha256'=>$id,'created_at'=>'2026-10-27T10:00:00Z','key_id'=>'synthetic-v1','encoding'=>'json-base64-no-compression','issuer_id'=>$f['vault']->identity,'issuer_mac'=>hash_hmac('sha256','f6d-issued:'.$id,$f['vault']->capability()[1])]);$path=operationsPath($f['vault'],$id.'.sealed');file_put_contents($path,$f['crypto']->encrypt($plain,'f6d-backup:'.$id));chmod($path,0600);return $id;}
test('F6-D actual encrypted backup verifies bounded DB and private sample files',function(): void{$f=operationsFixture();$before=reconciliationState($f);$m=operationBackup($f);same('VERIFIED',$m['state']);same(4,$m['file_count']);same(26,$m['counts']['f6b_entities']);same('XCHACHA20-POLY1305-IETF',$m['algorithm']);same($before,reconciliationState($f));same('NOT_VERIFIED',$m['original_archive_bytes']);same('NOT_VERIFIED',$m['production_backup']);});
test('F6-D backup identity is deterministic while native crypto uses fresh nonces',function(): void{$f=operationsFixture();$a=operationBackup($f);$path=operationsPath($f['vault'],$a['backup_id'].'.sealed');$before=file_get_contents($path);$b=operationBackup($f);same($a['backup_id'],$b['backup_id']);same(true,$b['replay']);same($before,file_get_contents($path));same(false,$f['crypto']->encrypt('SYNTHETIC','context')===$f['crypto']->encrypt('SYNTHETIC','context'));});
test('F6-D reports contain no keys tokens paths private bodies or ciphertext',function(): void{$f=operationsFixture();$m=operationBackup($f);$raw=json_encode([$m,$f['vault']->status()],JSON_THROW_ON_ERROR);foreach([$f['key'],base64_encode($f['key']),$f['vault']->capability()[1],$f['params'][3],operationsPath($f['vault']),'SYNTHETIC message private','relative_path','token_hash'] as $secret){same(false,str_contains($raw,$secret));}same('REQUIRES_KEY_AUTHENTICATION',$f['vault']->status()['verification']);});
test('F6-D wrong rotated missing revoked and mismatched key identities fail closed',function(): void{$f=operationsFixture();$m=operationBackup($f);foreach([new Crypto(random_bytes(32),'synthetic-v1'),new Crypto($f['key'],'rotated-v2')] as $key){raises(RuntimeException::class,fn()=>$f['vault']->verify($m['backup_id'],$key,'synthetic-v1'));}raises(TypeError::class,fn()=>$f['vault']->verify($m['backup_id'],null,'synthetic-v1'));raises(InvalidArgumentException::class,fn()=>$f['vault']->verify($m['backup_id'],$f['crypto'],'synthetic-v1',true));raises(InvalidArgumentException::class,fn()=>$f['vault']->verify($m['backup_id'],$f['crypto'],'wrong-id'));same('VERIFIED',$f['vault']->verify($m['backup_id'],$f['crypto'],'synthetic-v1')['state']);});
test('F6-D ciphertext tag truncation and missing package cannot verify',function(): void{foreach(['tamper','tag','truncated','missing','oversized'] as $fault){$f=operationsFixture();$m=operationBackup($f);$path=operationsPath($f['vault'],$m['backup_id'].'.sealed');$raw=file_get_contents($path);if($fault==='missing'){unlink($path);}elseif($fault==='oversized'){file_put_contents($path,str_repeat('x',4194305));}else{if($fault==='truncated'){$raw=substr($raw,0,30);}else{$at=$fault==='tag'?strlen($raw)-4:40;$raw[$at]=$raw[$at]==='A'?'B':'A';}file_put_contents($path,$raw);}raises(Throwable::class,fn()=>$f['vault']->verify($m['backup_id'],$f['crypto'],'synthetic-v1'));same('REQUIRES_KEY_AUTHENTICATION',$f['vault']->status()['verification']);}});
test('F6-D source file missing corrupt size or snapshot mismatch prevents complete backup',function(): void{foreach(['missing','corrupt','size','snapshot'] as $fault){$f=operationsFixture();$root=operationsPath($f['source']->samples);$file=glob($root.'/*.pdf')[0];if($fault==='missing'){unlink($file);}elseif($fault==='snapshot'){$p=$root.'/source-snapshot.json';$x=json_decode(file_get_contents($p),true,8,JSON_THROW_ON_ERROR);$x['snapshot']='wrong-snapshot';file_put_contents($p,json_encode($x,JSON_THROW_ON_ERROR));}else{file_put_contents($file,$fault==='size'?str_repeat('x',70000):'SYNTHETIC CORRUPT');}raises(Throwable::class,fn()=>operationBackup($f));same(0,$f['vault']->status()['sealed_candidates']);}});
test('F6-D traversal absolute sibling Unicode case and unknown file types are rejected',function(): void{$f=operationsFixture();foreach(['../secret.pdf','/tmp/private.pdf','C:/private.pdf','../sibling/data.pdf','Attachment-aaaaaaaaaaaaaaaa.pdf','attachment-é.pdf','attachment-aaaaaaaaaaaaaaaa.exe'] as $name){$id=operationForge($f,static function(array $d)use($name): array{$old=array_key_first($d['files']);$d['files'][$name]=$d['files'][$old];unset($d['files'][$old]);return $d;});raises(InvalidArgumentException::class,fn()=>$f['vault']->verify($id,$f['crypto'],'synthetic-v1'));}});
test('F6-D foreign owner checksum and inventory loss block authenticated malformed packages',function(): void{$f=operationsFixture();foreach(['owner','checksum','missing','logical'] as $fault){$id=operationForge($f,static function(array $d)use($fault): array{$name=array_key_first($d['files']);if($fault==='owner'){$d['files'][$name]['customer_key']=str_repeat('f',64);}elseif($fault==='checksum'){$d['files'][$name]['sha256']=str_repeat('f',64);}elseif($fault==='missing'){unset($d['files'][$name]);}else{$d['tables']['f6b_entities'][0]['payload_hash']=str_repeat('f',64);}return $d;});raises(InvalidArgumentException::class,fn()=>$f['vault']->verify($id,$f['crypto'],'synthetic-v1'));}});
test('F6-D physical source symlink is denied where platform capability exists',function(): void{$f=operationsFixture();if(PHP_OS_FAMILY==='Windows'){same('Windows',PHP_OS_FAMILY);return;}$file=glob(operationsPath($f['source']->samples).'/*.pdf')[0];unlink($file);symlink(operationsPath($f['vault'],'lease.json'),$file);raises(InvalidArgumentException::class,fn()=>operationBackup($f));same(0,$f['vault']->status()['sealed_candidates']);});
test('F6-D environment explicit authority wrong vault and expired lease fail closed',function(): void{$f=operationsFixture();raises(InvalidArgumentException::class,fn()=>Vault::open('../public',str_repeat('a',64)));raises(InvalidArgumentException::class,fn()=>Vault::open($f['vault']->identity,str_repeat('f',64)));try{putenv('SYNTHETIC_BACKUP_ALLOWED=0');raises(InvalidArgumentException::class,fn()=>operationBackup($f));putenv('SYNTHETIC_BACKUP_ALLOWED=1');putenv('APP_ENV=staging');raises(InvalidArgumentException::class,fn()=>operationBackup($f));}finally{putenv('APP_ENV=test');putenv('SYNTHETIC_BACKUP_ALLOWED=1');}$p=operationsPath($f['vault'],'lease.json');$lease=json_decode(file_get_contents($p),true,8,JSON_THROW_ON_ERROR);$lease['expires']=time()-1;file_put_contents($p,json_encode($lease,JSON_THROW_ON_ERROR));raises(InvalidArgumentException::class,fn()=>operationBackup($f));});
test('F6-D 1 4 8 independent backup processes publish one immutable artifact',function(): void{foreach([1,4,8] as $count){$f=operationsFixture();$id=null;foreach(operationsChildren($f,$count) as $child){same(0,$child['exit']);same(true,$child['stderr_empty']);same('VERIFIED',$child['result']['state']);$id??=$child['result']['backup_id'];same($id,$child['result']['backup_id']);}same(1,$f['vault']->status()['sealed_candidates']);}});
test('F6-D real process crashes at capture encryption manifest and publish never expose final',function(): void{foreach(['CRASH_BEFORE','CRASH_DB','CRASH_FILES_CAPTURE','CRASH_CAPTURE','CRASH_MANIFEST','CRASH_ENCRYPT','CRASH_PUBLISH'] as $fault){$f=operationsFixture();$child=operationsChildren($f,1,'BACKUP',$fault)[0];same(73,$child['exit']);same(0,$f['vault']->status()['sealed_candidates']);same('VERIFIED',operationBackup($f)['state']);same(1,$f['vault']->status()['sealed_candidates']);}});
test('F6-D controlled short write disk budget and stale operation do not verify partial files',function(): void{foreach(['DISK_FULL','EXPIRE'] as $fault){$f=operationsFixture();raises(RuntimeException::class,fn()=>$f['vault']->backup($f['source'],$f['crypto'],'synthetic-v1',$fault));same(0,$f['vault']->status()['sealed_candidates']);same(1,$f['vault']->status()['partial_or_failed']);same('VERIFIED',operationBackup($f)['state']);}});
test('F6-D escrow restore preserves exact DB evidence finance and sample file bytes',function(): void{$f=operationsFixture();$m=operationBackup($f);$t=operationsTarget($f);$r=$f['vault']->restore($m['backup_id'],$f['crypto'],'synthetic-v1',$t['target']);same('VERIFIED',$r['escrow_restore']);same($m['logical_sha256'],$r['logical_sha256']);same($m['finance'],$r['finance']);same(4,$r['files']);same('BLOCKED_IDENTITY_BOUND',$r['native_application_restore']);same('BLOCKED_IDENTITY_BOUND',$r['f6c_activation']);same(0,$r['provider_create']);same(true,$f['vault']->restore($m['backup_id'],$f['crypto'],'synthetic-v1',$t['target'])['replay']);});
test('F6-D wrong target marker ownership lease grants and schema are denied',function(): void{foreach(['marker','lease','grant','schema'] as $fault){$f=operationsFixture();$m=operationBackup($f);$t=operationsTarget($f);if($fault==='marker'){$t['setup']->execute('UPDATE f6d_restore_marker SET token_hash=?',[str_repeat('a',64)]);}elseif($fault==='lease'){$t['setup']->execute('UPDATE f6d_restore_marker SET expires_at=DATE_SUB(UTC_TIMESTAMP(6),INTERVAL 1 SECOND)');}elseif($fault==='grant'){$f['root']->execute("GRANT UPDATE ON `".$t['schema']."`.f6b_entities TO '".$t['user']."'@'".$f['host']."'");}else{$t['setup']->execute('ALTER TABLE f6b_entities ADD COLUMN unsupported INT NULL');}raises(Throwable::class,fn()=>$f['vault']->restore($m['backup_id'],$f['crypto'],'synthetic-v1',$t['target']));same(0,(int)$t['setup']->execute('SELECT COUNT(*) FROM f6b_entities')->fetchColumn());}});
test('F6-D corrupted backup and wrong key leave owned destination empty',function(): void{$f=operationsFixture();$m=operationBackup($f);$t=operationsTarget($f);raises(Throwable::class,fn()=>$f['vault']->restore($m['backup_id'],new Crypto(random_bytes(32),'synthetic-v1'),'synthetic-v1',$t['target']));file_put_contents(operationsPath($f['vault'],$m['backup_id'].'.sealed'),'corrupt');raises(Throwable::class,fn()=>$f['vault']->restore($m['backup_id'],$f['crypto'],'synthetic-v1',$t['target']));same(0,(int)$t['setup']->execute('SELECT COUNT(*) FROM f6b_runs')->fetchColumn());});
test('F6-D restore exception and real crashes rollback or re-read exact durable outcome',function(): void{foreach(['FAIL_INSERT','CRASH_INSERT','CRASH_FILES','CRASH_COMMIT'] as $fault){$f=operationsFixture();$m=operationBackup($f);$t=operationsTarget($f);if($fault==='FAIL_INSERT'){raises(RuntimeException::class,fn()=>$f['vault']->restore($m['backup_id'],$f['crypto'],'synthetic-v1',$t['target'],$fault));}else{same(73,operationsChildren($f,1,'RESTORE',$fault,$t)[0]['exit']);}same($fault==='CRASH_COMMIT'?26:0,(int)$t['setup']->execute('SELECT COUNT(*) FROM f6b_entities')->fetchColumn());same('VERIFIED',$f['vault']->restore($m['backup_id'],$f['crypto'],'synthetic-v1',$t['target'])['escrow_restore']);}});
test('F6-D existing conflicting restore rows are never overwritten or rebound',function(): void{$f=operationsFixture();$m=operationBackup($f);$t=operationsTarget($f);$t['setup']->execute('INSERT INTO f6b_entities VALUES(?,?,?,?,?,?)',[str_repeat('a',64),str_repeat('b',64),'customer',null,'{}',Contract::hash([])]);raises(InvalidArgumentException::class,fn()=>$f['vault']->restore($m['backup_id'],$f['crypto'],'synthetic-v1',$t['target']));same(1,(int)$t['setup']->execute('SELECT COUNT(*) FROM f6b_entities')->fetchColumn());raises(TypeError::class,fn()=>$t['target']->restore([]));});
test('F6-D source readiness lost migration checksum partial schema or evidence cannot back up',function(): void{foreach(['migration','checksum','column','provenance'] as $fault){$f=operationsFixture();if($fault==='migration'){$f['setup']->execute("UPDATE schema_migrations SET status='APPLYING'");}elseif($fault==='checksum'){$f['setup']->execute('UPDATE schema_migrations SET checksum=?',[str_repeat('a',64)]);}elseif($fault==='column'){$f['setup']->execute('ALTER TABLE f6b_entities ADD COLUMN unsupported INT NULL');}else{$f['setup']->execute('UPDATE f6b_provenance SET envelope_hash=?',[str_repeat('a',64)]);}raises(Throwable::class,fn()=>operationBackup($f));same(0,$f['vault']->status()['sealed_candidates']);}});
test('F6-D actual source connection loss prevents publication and fresh reconnect recovers',function(): void{$f=operationsFixture();$ids=$f['root']->execute('SELECT ID FROM information_schema.PROCESSLIST WHERE USER=?',[$f['reader_params'][1]])->fetchAll(PDO::FETCH_COLUMN);foreach($ids as $id){$f['root']->execute('KILL CONNECTION '.(int)$id);}raises(Throwable::class,fn()=>operationBackup($f));same(0,$f['vault']->status()['sealed_candidates']);$f['source']=\Hostider\Migration\Operations\Snapshot::open($f['sandbox'],...[...$f['reader_params'],$f['source']->samples]);same('VERIFIED',operationBackup($f)['state']);});
test('F6-D dry retention uses tier union and protects the last recoverable verified copy',function(): void{$items=[];for($i=0;$i<100;++$i){$items[]=['id'=>hash('sha256','backup'.$i),'created_at'=>gmdate('Y-m-d\TH:i:s\Z',strtotime('2026-10-27T00:00:00Z')-$i*86400),'bytes'=>100,'state'=>'VERIFIED','key_available'=>true];}$r=Retention::plan($items,'2026-10-27T00:00:00Z',20000);same(14,count($r['tiers']['daily']));same(8,count($r['tiers']['weekly']));same(true,in_array($items[0]['id'],$r['protected'],true));same(false,$r['deletion_performed']);$old=[['id'=>hash('sha256','old'),'created_at'=>'2020-01-01T00:00:00Z','bytes'=>1,'state'=>'VERIFIED','key_available'=>true]];same([] ,Retention::plan($old,'2026-10-27T00:00:00Z',10)['delete_candidates']);});
test('F6-D retention clock key loss incomplete chain quota and timezone produce review not deletion',function(): void{$items=[['id'=>str_repeat('a',64),'created_at'=>'2027-01-01T00:00:00Z','bytes'=>100,'state'=>'VERIFIED','key_available'=>true],['id'=>str_repeat('b',64),'created_at'=>'2026-01-01T00:00:00Z','bytes'=>100,'state'=>'FAILED','key_available'=>false]];$r=Retention::plan($items,'2026-10-27T00:00:00Z',10);same(true,in_array('FUTURE_CLOCK',$r['reasons'],true));same(true,in_array('NO_KNOWN_GOOD_RECOVERABLE_COPY',$r['reasons'],true));same(true,in_array('QUOTA_THRESHOLD',$r['reasons'],true));same([],$r['delete_candidates']);raises(InvalidArgumentException::class,fn()=>Retention::plan($items,'2026-10-27T00:00:00+03:00',10));});
test('F6-D native Queue expiry keeps unsafe outcome UNKNOWN and rejects stale owner finish',function(): void{$f=operationsFixture();$t=operationsTarget($f);foreach(['001_f0_infrastructure.php','002_f0_1_retention.php'] as $name){foreach(require dirname(__DIR__).'/migrations/'.$name as $sql){$t['setup']->execute($sql);}}$db=$t['setup'];$q=new Queue($db);$db->transaction(fn()=>$q->enqueue('F6D_SYNTHETIC_PROBE',['classification'=>'SYNTHETIC'],'probe',Id::uuid(),false));$lease=$q->claim();same(true,is_array($lease));$wrong=$lease;$wrong['lease_token']=Id::uuid();raises(RuntimeException::class,fn()=>$q->finish($wrong,'SUCCEEDED'));$db->execute('UPDATE jobs SET leased_until=DATE_SUB(UTC_TIMESTAMP(6),INTERVAL 1 SECOND)');same(null,$q->claim());same('UNKNOWN',$db->execute('SELECT status FROM jobs')->fetchColumn());raises(RuntimeException::class,fn()=>$q->finish($lease,'SUCCEEDED'));same(0,$f['vault']->status()['sealed_candidates']);});
test('F6-D native retry-safe poison work reaches DLQ without dispatching other engines',function(): void{$f=operationsFixture();$t=operationsTarget($f);foreach(['001_f0_infrastructure.php','002_f0_1_retention.php'] as $name){foreach(require dirname(__DIR__).'/migrations/'.$name as $sql){$t['setup']->execute($sql);}}$db=$t['setup'];$q=new Queue($db);$db->transaction(fn()=>$q->enqueue('F6D_SYNTHETIC_POISON',['classification'=>'SYNTHETIC'],'poison',Id::uuid(),true));$db->execute('UPDATE jobs SET max_attempts=1');$lease=$q->claim();$q->finish($lease,'FAILED');same('FAILED',$db->execute('SELECT status FROM jobs')->fetchColumn());same(1,(int)$db->execute('SELECT COUNT(*) FROM dead_letters')->fetchColumn());same(null,$q->claim());same(0,$f['vault']->status()['sealed_candidates']);});
test('F6-D destination least privilege denies UPDATE DELETE DDL and cross-schema reads',function(): void{$f=operationsFixture();$t=operationsTarget($f);$p=$t['params'];$db=\Hostider\Core\Database\Database::connect(new \Hostider\Core\Config('test','https://synthetic.example.invalid',base64_encode(random_bytes(32)),'mysql:host=127.0.0.1;port='.$p[0].';dbname='.$p[1].';charset=utf8mb4',$p[2],$p[3]));foreach(['UPDATE f6b_entities SET owner_key=owner_key','DELETE FROM f6b_history','CREATE TABLE forbidden(id INT)','SELECT * FROM mysql.user'] as $sql){raises(PDOException::class,fn()=>$db->execute($sql));}raises(InvalidArgumentException::class,fn()=>Destination::open(3306,'production','root','real','secret',$t['files']));raises(RuntimeException::class,fn()=>Destination::open(...[...$t['params'],$f['vault']]));});
test('F6-D compression version duplicate archive key and partial manifest cannot authenticate',function(): void{$f=operationsFixture();$data=$f['source']->capture();$id=Contract::hash($data);foreach(['gzip','unknown-v99','duplicate','partial'] as $fault){$v=['data'=>$data,'logical_sha256'=>$id,'created_at'=>'2026-10-27T10:00:00Z','key_id'=>'synthetic-v1','encoding'=>$fault==='gzip'?'gzip':'json-base64-no-compression'];if($fault==='unknown-v99'){$v['data']['contract']='unknown-v99';}if($fault==='duplicate'){$v['data']['files'][]=reset($v['data']['files']);}if($fault==='partial'){unset($v['data']['tables']['f6b_mappings']);}$raw=$f['crypto']->encrypt(CanonicalJson::encode($v),'f6d-backup:'.$id);raises(Throwable::class,fn()=>AuthenticatedBackup::open($id,$raw,$f['crypto'],'synthetic-v1',$f['vault']));}});
test('F6-D dry retention rejects duplicate identities and never performs filesystem deletion',function(): void{$a=['id'=>str_repeat('a',64),'created_at'=>'2026-01-01T00:00:00Z','bytes'=>1,'state'=>'VERIFIED','key_available'=>true];raises(InvalidArgumentException::class,fn()=>Retention::plan([$a,$a],'2026-10-27T00:00:00Z',10));same(false,Retention::plan([$a],'2026-10-27T00:00:00Z',10)['deletion_performed']);$a['requires']=[str_repeat('b',64)];raises(InvalidArgumentException::class,fn()=>Retention::plan([$a],'2026-10-27T00:00:00Z',10));});
test('F6-D native Worker executes only an explicitly registered synthetic backup handler',function(): void{$f=operationsFixture();$t=operationsTarget($f);foreach(['001_f0_infrastructure.php','002_f0_1_retention.php'] as $name){foreach(require dirname(__DIR__).'/migrations/'.$name as $sql){$t['setup']->execute($sql);}}$db=$t['setup'];$q=new Queue($db);$worker=new \Hostider\Core\Queue\Worker($db,$q);$worker->register('F6D_SYNTHETIC_BACKUP',function(array $payload)use($f): string{same('SYNTHETIC',$payload['classification']);same('VERIFIED',$f['vault']->backup($f['source'],$f['crypto'],'synthetic-v1')['state']);return 'SUCCEEDED';});$db->transaction(fn()=>$q->enqueue('F6D_SYNTHETIC_BACKUP',['classification'=>'SYNTHETIC'],'backup',Id::uuid(),false));same(true,$worker->once());same(false,$worker->once());same('SUCCEEDED',$db->execute('SELECT status FROM jobs')->fetchColumn());same(1,$f['vault']->status()['sealed_candidates']);});
test('F6-D operations module has no provider finance mail transport or public endpoint dependency',function(): void{foreach(glob(dirname(__DIR__).'/src/Migration/Operations/*.php') as $path){$code=file_get_contents($path);same(0,preg_match('/Hostider\\\\(?:Providers|Services|Cloud|Domains|Payments|Support)\\\\|\b(?:curl_exec|mail|stream_socket_client|fsockopen|shell_exec|proc_open|unserialize)\s*\(/',$code));}});
